const sql=new DatabaseSync(':memory:');
for(const f of (await readdir('drizzle')).filter(x=>x.endsWith('.sql')).sort())sql.exec(await readFile(join('drizzle',f),'utf8'));
function prepared(query,args=[]){const statement=()=>sql.prepare(query);return {
 bind(...values){return prepared(query,values)},
 async first(){return statement().get(...args)||null},
 async all(){return {results:statement().all(...args),success:true}},
 async run(){const r=statement().run(...args);return {success:true,meta:{changes:Number(r.changes),last_row_id:Number(r.lastInsertRowid)}}}
};}
const storedObjects=new Map();
const bindings={DB:{prepare:q=>prepared(q),async batch(stmts){sql.exec('BEGIN');try{const r=[];for(const s of stmts)r.push(await s.run());sql.exec('COMMIT');return r}catch(e){sql.exec('ROLLBACK');throw e}}},BUCKET:{async put(key,bytes){storedObjects.set(key,new Uint8Array(bytes))},async get(key){const data=storedObjects.get(key);return data?{body:new Blob([data]).stream(),size:data.length,arrayBuffer:async()=>data.buffer.slice(data.byteOffset,data.byteOffset+data.byteLength)}:null},async delete(key){storedObjects.delete(key)}},TOKEN_ENCRYPTION_KEY:Buffer.alloc(32,7).toString('base64')};
globalThis.__testEnv=bindings;
