const {inflateSync,deflateSync}=await import('node:zlib');
function pixelsFromPng(bytes){let at=8;const compressed=[];let w=0,h=0;while(at<bytes.length){const n=new DataView(bytes.buffer,bytes.byteOffset+at,4).getUint32(0),name=String.fromCharCode(...bytes.subarray(at+4,at+8));if(name==='IHDR'){w=new DataView(bytes.buffer,bytes.byteOffset+at+8,8).getUint32(0);h=new DataView(bytes.buffer,bytes.byteOffset+at+8,8).getUint32(4);}if(name==='IDAT')compressed.push(bytes.subarray(at+8,at+8+n));at+=n+12;}const scan=inflateSync(Buffer.concat(compressed)),rgb=new Uint8Array(w*h*3);for(let y=0;y<h;y++){assert.equal(scan[y*(w*3+1)],0);rgb.set(scan.subarray(y*(w*3+1)+1,(y+1)*(w*3+1)),y*w*3);}return rgb;}
const backgroundPixels=pixelsFromPng(png);const uploadForm=()=>{const fd=new FormData();fd.set('png',new Blob([png],{type:'image/png'}),'canva.png');fd.set('pixels',new Blob([deflateSync(backgroundPixels)]),'pixels.deflate');fd.set('kind','daily');fd.set('name','My Canva background.png');return fd;};
let fd=uploadForm();let uploadResponse=await route.POST(new Request('https://studio.test/api/church/template',{method:'POST',headers:{'oai-authenticated-user-id':'template-owner',Origin:'https://studio.test'},body:fd}));assert.equal(uploadResponse.status,400);fd=uploadForm();fd.set('rightsConfirmed','yes');uploadResponse=await route.POST(new Request('https://studio.test/api/church/template',{method:'POST',headers:{'oai-authenticated-user-id':'template-owner',Origin:'https://studio.test'},body:fd}));assert.equal(uploadResponse.status,200);const template=await uploadResponse.json();assert.ok(template.id);check('Canva PNG uploads validate dimensions and require design-rights confirmation');
const templateConfig={...cm.churchDefaults,templates:{daily:{...cm.defaultTemplateUse,id:template.id,textColor:'#112233',panelOpacity:.6}}};assert.equal((await call('church/settings','template-owner',templateConfig)).status,200);assert.equal((await call('church/settings','unrelated-owner',templateConfig)).status,400);const customSpec=cm.makeChurchContent(templateConfig,'daily','2026-12-01').spec;const customPng=await images.renderChurchImage(customSpec,backgroundPixels);const actualPixels=pixelsFromPng(customPng);assert.deepEqual([...actualPixels.subarray(0,30)],[...backgroundPixels.subarray(0,30)]);assert.ok(!Buffer.from(customPng).equals(Buffer.from(png)));await writeFile('.sites-runtime/tests/church-template-overlay.png',customPng);check('uploaded Canva backgrounds retain their pixels outside the dynamic text area and accept owner-scoped layout settings');


